// Signs the overdue-loans fetch. runDate is "today" in GENERIC_TIMEZONE, which
// must equal APP_TIME_ZONE on Convex so both sides agree on what "overdue" means.
const crypto = require('crypto');

const secret = $env.CONVEX_INBOUND_SECRET;
if (!secret) throw new Error('CONVEX_INBOUND_SECRET is not set');

const timeZone = $env.GENERIC_TIMEZONE || 'Asia/Jakarta';
// en-CA formats as YYYY-MM-DD.
const runDate = new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const executionId = String($execution.id);

const rawBody = JSON.stringify({ runDate, executionId });
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = 'v1=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`, 'utf8').digest('hex');

return [{ json: { runDate, executionId, startedAt: Date.now(), rawBody, timestamp, signature } }];

// One item per overdue loan, built from the minimized OverdueLoanForN8n fields only.
const appUrl = String($env.APP_URL || 'http://localhost:3000').replace(/\/+$/, '');
const from = $env.MAIL_FROM || 'LendLoop <no-reply@lendloop.local>';
const fmtDay = (iso) =>
  new Date(`${iso}T00:00:00Z`).toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' });

const loans = $('Fetch overdue loans').first().json.loans || [];
const out = [];
for (const loan of loans) {
  const ok =
    loan &&
    typeof loan.idempotencyKey === 'string' &&
    typeof loan.loanId === 'string' &&
    typeof loan.toolName === 'string' &&
    typeof loan.endDate === 'string' &&
    typeof loan.recipientFirstName === 'string' &&
    typeof loan.recipientEmail === 'string';
  if (!ok) {
    console.log('[lendloop] overdue loan skipped: incomplete record');
    continue;
  }
  const days = Number(loan.daysOverdue) || 1;
  const link = `${appUrl}/loans/${encodeURIComponent(loan.loanId)}`;
  const text = [
    `Hi ${loan.recipientFirstName},`,
    '',
    `${loan.toolName} was due back on ${fmtDay(loan.endDate)} (${days} ${days === 1 ? 'day' : 'days'} overdue). Please return it to the owner.`,
    '',
    'Open the loan in LendLoop:',
    link,
    '',
    '— LendLoop',
    `Ref ${loan.loanId}. You get this reminder once a day while the loan is overdue.`,
  ].join('\n');
  out.push({
    json: {
      idempotencyKey: loan.idempotencyKey,
      loanId: loan.loanId,
      attempt: Number.isInteger(loan.attempt) && loan.attempt >= 1 ? loan.attempt : 1,
      from,
      to: loan.recipientEmail,
      subject: `Reminder: ${loan.toolName} is ${days} ${days === 1 ? 'day' : 'days'} overdue`,
      text,
    },
  });
}
return out;

// The Merge node collects both outputs of "Send reminder": success items carry
// the SMTP result, error items carry `error`. Each is paired back to its loan.
// "Write back reminder" signs and posts each body.
const executionId = String($execution.id);

return $input.all().map((item, i) => {
  const loan = $('Prepare reminders').itemMatching(i).json;
  const status = item.json.error === undefined ? 'sent' : 'failed';
  const body = { idempotencyKey: loan.idempotencyKey, status, attempt: loan.attempt, executionId, channel: 'email' };
  if (status === 'failed') body.errorCategory = 'delivery_failed';
  return { json: { idempotencyKey: loan.idempotencyKey, status, rawBody: JSON.stringify(body) } };
});

// POSTs each loan's write-back to /n8n/deliveries with its own retries: up to
// 3 tries, 5 s apart. (An HTTP Request node's Retry On Fail only looks at the
// FIRST item, so it would skip a later loan's failed write-back and re-post
// the ones that already succeeded.) Every try is signed afresh over the same
// body, so the idempotency key is unchanged and a slow run never trips the
// 300 s replay window. One output item per input, in order, for "Summarize
// run": {ok, duplicate}, or {error} when the write-back never landed.
const crypto = require('crypto');

const secret = $env.CONVEX_INBOUND_SECRET;
if (!secret) throw new Error('CONVEX_INBOUND_SECRET is not set');
const url = `${String($env.CONVEX_SITE_URL || '').replace(/\/+$/, '')}/n8n/deliveries`;
const helpers = this.helpers;

const TRIES = 3;
const WAIT_MS = 5000;
// Stay well inside N8N_RUNNERS_TASK_TIMEOUT: once spent, the remaining loans
// get no more retries and are counted as failed in the run summary.
const BUDGET_MS = 200000;
const started = Date.now();
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
// No answer, 429 and 5xx can succeed later; any other 4xx (bad signature,
// unknown loan, bad body) would only be rejected again.
const retryable = (code) => code === 0 || code === 429 || code >= 500;

async function post(idempotencyKey, rawBody) {
  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = 'v1=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`, 'utf8').digest('hex');
  try {
    const res = await helpers.httpRequest({
      method: 'POST',
      url,
      headers: {
        'Content-Type': 'application/json',
        'X-LendLoop-Timestamp': timestamp,
        'X-LendLoop-Signature': signature,
        'X-Idempotency-Key': idempotencyKey,
      },
      body: rawBody,
      json: false,
      timeout: 10000,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
    });
    const code = Number(res.statusCode) || 0;
    if (code < 200 || code >= 300) return { code };
    const body = typeof res.body === 'string' ? JSON.parse(res.body) : res.body;
    return { code, result: { ok: body.ok === true, duplicate: body.duplicate === true } };
  } catch (e) {
    return { code: 0 }; // timeout, refused, DNS, or an unreadable 2xx body
  }
}

const out = [];
for (const item of $input.all()) {
  const { idempotencyKey, rawBody } = item.json;
  let last = { code: 0 };
  for (let attempt = 1; attempt <= TRIES; attempt++) {
    if (attempt > 1) {
      if (!retryable(last.code) || Date.now() - started > BUDGET_MS) break;
      await sleep(WAIT_MS);
    }
    last = await post(idempotencyKey, rawBody);
    if (last.result) break;
  }
  if (!last.result) {
    // Key and status only: never the body (it names the loan) or the signature.
    console.log(`[lendloop] reminder write-back failed key=${idempotencyKey} status=${last.code || 'no_response'}`);
  }
  out.push({ json: last.result || { error: 'write_back_failed', statusCode: last.code } });
}
return out;

// Aggregates the run and signs POST /n8n/reminder-runs. Runs on both paths:
// after the write-backs, or straight from "Any overdue loans?" when none were found.
const crypto = require('crypto');

const secret = $env.CONVEX_INBOUND_SECRET;
if (!secret) throw new Error('CONVEX_INBOUND_SECRET is not set');

const req = $('Sign overdue-loans request').first().json;
const fetched = $('Fetch overdue loans').first().json;

let signed = [];
let results = [];
try {
  signed = $('Build write-backs').all();
  results = $('Write back reminder').all();
} catch (e) {
  // Zero overdue loans: the write-back branch never ran.
}

let sent = 0;
let failed = 0;
let duplicates = 0;
signed.forEach((s, i) => {
  const r = results[i] ? results[i].json : {};
  const writeBackFailed = r.error !== undefined;
  if (s.json.status === 'sent' && !writeBackFailed) sent++;
  else failed++;
  if (r.duplicate === true) duplicates++;
});

// Convex leaves out loans already reminded for runDate and only counts them
// (OverdueLoansResponse.skipped), so "found" is every overdue loan.
const skipped = Number.isInteger(fetched.skipped) && fetched.skipped > 0 ? fetched.skipped : 0;
const body = {
  executionId: req.executionId,
  runDate: req.runDate,
  found: (Array.isArray(fetched.loans) ? fetched.loans.length : 0) + skipped,
  sent,
  skipped,
  duplicates,
  failed,
  durationMs: Date.now() - req.startedAt,
};

const rawBody = JSON.stringify(body);
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = 'v1=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`, 'utf8').digest('hex');

console.log(
  `[lendloop] reminder run ${body.runDate} execution=${body.executionId} found=${body.found} sent=${sent} failed=${failed} duplicates=${duplicates} skipped=${body.skipped}`,
);
return [{ json: { ...body, rawBody, timestamp, signature } }];
